// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, Img, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type SocialShuffleProps = Record<string, any>;

const SocialShuffle: React.FC<SocialShuffleProps> = ({
  backgroundColor = "#111111",
  transparentBackground = true,
  durationInSeconds = 10,
  platformImages = [
    "https://malloy.blob.core.windows.net/web/testing/socialicons/Youtube.png",
    "https://malloy.blob.core.windows.net/web/testing/socialicons/Instagram.png",
    "https://malloy.blob.core.windows.net/web/testing/socialicons/Tik Tok.png",
    "https://malloy.blob.core.windows.net/web/testing/socialicons/Snapchat.png",
    "https://malloy.blob.core.windows.net/web/testing/socialicons/Linkedin.png"
  ],
  shuffleIntervalFrames = 10,
  iconSize = 300,
}) => {
  useFontLoader(["Inter"]);
  
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  
  const safeImages = platformImages.length > 0 ? platformImages : [
    "https://placehold.co/400x400/png?text=No+Image"
  ];

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  
  // Calculate which image to show
  const index = Math.floor(frame / shuffleIntervalFrames);
  const currentImageIndex = index % safeImages.length;
  const activeImage = safeImages[currentImageIndex];

  // Spring animation triggered on every shuffle
  // We normalize the time so the spring resets every 'shuffleIntervalFrames'
  const framesSinceShuffle = frame % shuffleIntervalFrames;
  
  const scaleSpring = spring({
    frame: framesSinceShuffle,
    fps,
    config: {
      damping: 10,
      stiffness: 200,
      mass: 0.5,
    }
  });

  // Fade out/in effect slightly on change to smooth the transition
  const opacity = interpolate(
    framesSinceShuffle,
    [0, shuffleIntervalFrames * 0.2, shuffleIntervalFrames * 0.8, shuffleIntervalFrames],
    [0.8, 1, 1, 0.9],
    { extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", overflow: "hidden" }}>
      
      <AbsoluteFill style={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          gap: 40
      }}>
        
        {/* Shuffling Icon Container */}
        <div style={{
            width: iconSize,
            height: iconSize,
            position: 'relative',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center'
        }}>
            
            {/* The Image */}
            <Img 
                src={activeImage}
                style={{
                    width: '100%',
                    height: '100%',
                    objectFit: 'contain',
                    transform: `scale(${0.9 + (scaleSpring * 0.1)})`,
                    opacity: opacity,
                    zIndex: 1,
                    filter: 'drop-shadow(0 10px 20px rgba(0,0,0,0.25))'
                }}
            />
        </div>

      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default SocialShuffle;